package com.br.ifg.luziania.trabalhopw.resource;
import com.br.ifg.luziania.trabalhopw.dto.*;import com.br.ifg.luziania.trabalhopw.service.ClienteService;import jakarta.annotation.security.RolesAllowed;import jakarta.inject.Inject;import jakarta.validation.Valid;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;import java.util.List;
@Path("/clientes") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) @RolesAllowed({"ADMIN","ATENDENTE"})
public class ClienteResource {@Inject ClienteService service; @GET public List<ClienteDTO> listar(){return service.listar();} @POST public ClienteDTO criar(@Valid ClienteEntradaDTO dto){return service.criar(dto);} @PUT @Path("/{id}") public ClienteDTO atualizar(@PathParam("id") Long id,@Valid ClienteEntradaDTO dto){return service.atualizar(id,dto);} @DELETE @Path("/{id}") public void desativar(@PathParam("id") Long id){service.desativar(id);}}
